head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//메뉴이동

/**
 * @method
 * @name changePageKonex
 * @description desc
 * @param {string} ver1 desc
 * @param {string} ver2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.changePageKonex = function(ver1, ver2) {
    var form = document.moveForm;
    if ('1' == ver1) {
        form.nowPage.setValue(ver2);
    } else if ('2' == ver1) {
        form.nowPage.setValue('20');
        form.method.setValue('loadDetail');
    } else if ('3' == ver1) {
        form.nowPage.setValue('30');
        form.action = '/konex/bbs.do';
        form.method.setValue('searchCommentLetterList');
    } else if ('4' == ver1) {
        form.nowPage.setValue('40');
    } else if ('5' == ver1) {
        form.nowPage.setValue('50');
    } else if ('6' == ver1) {
        form.nowPage.setValue('60');
    } else if ('7' == ver1) {
        form.nowPage.setValue('19');
    }
    //alert(form.method.value);
    form.submit();
};
/**
 * @method
 * @name fn_print
 * @description 인쇄 — 화면 영역만 캡처해 인쇄 대화상자를 띄운다($c.win.print, 종전 window.print 대체)
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_print = async function() {
    try {
        await $c.win.print();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "listInvstgKonex.fn_print" });
    }
};
